import json,re
from pathlib import Path
base=Path('/Users/alexandremasmejean/.codex/.chatgpt-projects/g-p-6ad59c015c308191aa21cba63c71a6dc/sites/liberer-la-retraite/dist/corpus')
pat=re.compile(r'(?:1607\\s*bis|006306577)')
for file in sorted(base.glob('*.json')):
 if file.name.endswith('-structure.json'): continue
 data=json.loads(file.read_text())
 if isinstance(data,list):
  for a in data:
   if isinstance(a,dict):
    for k in ('source_xml','source_notes_xml'):
     x=a.get(k,'') or ''
     if pat.search(x): print(file.name,a.get('number'),k,'matches',len(pat.findall(x)))
s=json.load(open('source.json'))[0]
print('companion absent:', 'source_companions' not in s)
print('source_conflict_ids:', s.get('source_conflict_ids'))
